<template><main class="settings-shell"><header class="settings-header"><RouterLink to="/">←</RouterLink><div><p>THIS IS PUN</p><h1>玩家账户</h1></div></header><section class="settings-card"><template v-if="player.loggedIn"><h2>你好，{{ player.username }}</h2><p>登录后通关进度会同步到服务器。</p><button class="ghost-button" @click="player.logout">退出登录</button></template><template v-else><label class="settings-row"><span><strong>账号</strong></span><input v-model.trim="username" /></label><label class="settings-row"><span><strong>密码</strong></span><input v-model="password" type="password" /></label><p v-if="error" class="submit-error">{{ error }}</p><div class="answer-actions"><button class="secondary-button" @click="submit(true)">注册</button><button class="primary-button" @click="submit(false)">登录</button></div></template></section></main></template>
<script setup lang="ts">import { ref } from "vue"; import { usePlayerStore } from "../stores/player"; const player=usePlayerStore(); const username=ref(""); const password=ref(""); const error=ref(""); async function submit(register:boolean){try{error.value="";await player.login(username.value,password.value,register)}catch(e){error.value=e instanceof Error?e.message:"认证失败"}}</script>
